# SPDX-License-Identifier: GPL-3.0-or-later
# Regenerate deterministic golden tests from the vendored, unmodified R sources.
# Run from the entropy package directory: Rscript --vanilla validation/generate_reference.R
for (path in sort(list.files('upstream/R', full.names=TRUE))) source(path)
lines = c('! SPDX-License-Identifier: GPL-3.0-or-later',
          '! Generated by validation/generate_reference.R from entropy 1.3.2.',
          '! Reference runtime: GNU R 4.5.0. Do not hand-edit the numerical expectations.',
          'program test_r_reference',
          '   use entropy_module',
          '   use, intrinsic :: ieee_arithmetic, only : ieee_is_finite',
          '   implicit none',
          '   real(dp) :: y(4), z(4), table(2, 3), prior(4)',
          '   type(test_result) :: result',
          '   integer, allocatable :: bins(:), bins2(:, :)',
          '   integer :: status, checks',
          '   checks = 0')
add = function(...) lines <<- c(lines, ...)
fnum = function(x) {
  stopifnot(all(is.finite(x)))
  paste0(sprintf('%.17e', x), '_dp')
}
farray = function(x) paste0('[', paste(fnum(as.vector(x)), collapse=', '), ']')
check = function(expr, expected, label=expr) {
  label = gsub('"', '', label, fixed=TRUE)
  if(length(expected)==1) {
    add(paste0('   call check(',expr,', &'),
        paste0('      ', fnum(expected), ', "', label, '")'))
  } else {
    add(paste0('   call check_vector(',expr,', &'))
    for (i in seq_along(expected)) {
      add(paste0('      ',if(i==1)'[' else '',fnum(expected[i]),if(i==length(expected))paste0('], "',label,'")') else ', &'))
    }
  }
}
ys = list(c(3,1,0,6),c(10,2,3,1),c(1,1,1,1),c(0,0,1,0))
zs = list(c(2,4,1,3),c(5,5,5,5),c(2,3,5,7),c(1,1,1,1))
tabs = list(matrix(c(5,1,2,6,3,4),2),matrix(c(1,8,3,2,5,9),2),matrix(c(1,1,2,2,3,3),2),matrix(c(1,0,0,1,0,1),2))
for (case in seq_along(ys)) {
  y=ys[[case]]
  z=zs[[case]]
  tab=tabs[[case]]
  add(paste0('   ! Reference scenario ',case),
      paste0('   y = ',farray(y)),paste0('   z = ',farray(z)),
      '   table = reshape([ &',paste0('      ',paste(fnum(tab[1:3]),collapse=', '),', &'),
      paste0('      ',paste(fnum(tab[4:6]),collapse=', '),'], [2, 3])'))
  check('freqs_empirical(y)',freqs.empirical(y))
  check('reshape(freqs_empirical(table), [6])',as.vector(freqs.empirical(tab)))
  check('freqs_dirichlet(y, 0.5_dp)',freqs.Dirichlet(y,.5))
  check('reshape(freqs_dirichlet(table, 0.5_dp), [6])',as.vector(freqs.Dirichlet(tab,.5)))
  prior=c(.1,.3,.7,1.2)
  add(paste0('   prior = ',farray(prior)))
  check('freqs_dirichlet(y, prior)',freqs.Dirichlet(y,prior))
  check('freqs_shrink(y)',freqs.shrink(y,verbose=FALSE))
  check('freqs_shrink(y, 0.35_dp)',freqs.shrink(y,.35,verbose=FALSE))
  check('reshape(freqs_shrink(table), [6])',as.vector(freqs.shrink(tab,verbose=FALSE)))
  check('shrinkage_intensity(y)',attr(freqs.shrink(y,verbose=FALSE),'lambda.freqs'))
  for (method in c('ML','Jeffreys','Laplace','SG','minimax','shrink')) {
    check(paste0('freqs(y, "',method,'")'),freqs(y,method=method,verbose=FALSE))
  }
  for (unit in c('log','log2','log10')) {
    for (op in c('entropy','mi','chi2indep','KL','chi2')) {
      arg = if(op %in% c('mi','chi2indep')) tab else y
      argname=if(op %in% c('mi','chi2indep')) 'table' else 'y'
      pair=op %in% c('KL','chi2')
      for(estimator in c('plugin','empirical','Dirichlet','shrink')) {
        args=list(arg)
        fargs=c(argname)
        if(pair) {
          args=c(args,list(z))
          fargs=c(fargs,'z')
        }
        if(estimator=='Dirichlet') {
          args=c(args,list(.5))
          fargs=c(fargs,'0.5_dp')
          if(pair) {
            args=c(args,list(.25))
            fargs=c(fargs,'0.25_dp')
          }
        }
        args$unit=unit
        fargs=c(fargs,paste0('unit="',unit,'"'))
        if(estimator=='shrink') args$verbose=FALSE
        rval=do.call(get(paste(op,estimator,sep='.')),args)
        check(paste0(tolower(op),'_',tolower(estimator),'(',paste(fargs,collapse=', '),')'),rval)
        if(estimator=='shrink') {
          if(pair) {
            args$lambda.freqs1=.25
            args$lambda.freqs2=.75
            fargs=c(argname,'z','0.25_dp','0.75_dp',paste0('unit="',unit,'"'))
          } else {
            args$lambda.freqs=.25
            fargs=c(argname,'0.25_dp',paste0('unit="',unit,'"'))
          }
          check(paste0(tolower(op),'_shrink(',paste(fargs,collapse=', '),')'),
                do.call(get(paste(op,estimator,sep='.')),args))
        }
      }
    }
    check(paste0('entropy_millermadow(y, "',unit,'")'),entropy.MillerMadow(y,unit))
    check(paste0('entropy_chaoshen(y, "',unit,'")'),entropy.ChaoShen(y,unit))
    for (method in c('ML','MM','Jeffreys','Laplace','SG','minimax','CS','shrink')) {
      check(paste0('entropy(y, "',method,'", "',unit,'")'),entropy(y,method=method,unit=unit,verbose=FALSE))
    }
    for(fn in c('Gstat','chi2stat','Gstatindep','chi2statindep')) {
      indep=grepl('indep',fn)
      args=if(indep) list(tab,unit=unit) else list(y,z,unit=unit)
      expected=do.call(get(fn),args)
      add(paste0('   result = ',tolower(fn),'(',if(indep)'table' else 'y, z',', "',unit,'")'))
      check('result%stat',expected$stat,paste(fn,unit,'stat'))
      check('real(result%df, dp)',expected$df,paste(fn,unit,'df'))
      check('result%pval',expected$pval,paste(fn,unit,'pval'))
    }
  }
}
x=c(0,.25,.5,.75,1)
add('   call discretize([0.0_dp, 0.25_dp, 0.5_dp, 0.75_dp, 1.0_dp], 4, bins, status=status)')
check('real(bins, dp)',as.vector(discretize(x,4)))
check('real(status, dp)',0)
add('   call discretize2d([0.0_dp, 0.25_dp, 0.5_dp, 0.75_dp, 1.0_dp], &',
    '      [1.0_dp, 0.75_dp, 0.5_dp, 0.25_dp, 0.0_dp], 2, 2, bins2, status=status)')
check('real(reshape(bins2, [4]), dp)',as.vector(discretize2d(x,rev(x),2,2)))
check('real(status, dp)',0)
add('   print *, "R reference checks passed:", checks',
    'contains',
    '   subroutine check(actual, expected, label)',
    '      real(dp), intent(in) :: actual !! Computed scalar from the Fortran translation.',
    '      real(dp), intent(in) :: expected !! Golden value evaluated by pinned upstream R entropy 1.3.2.',
    '      character(len=*), intent(in) :: label !! Name of the computational operation under comparison.',
    '      checks = checks + 1',
    '      if (.not. ieee_is_finite(actual)) then',
    '         print *, "Nonfinite result: ", label',
    '         error stop 1',
    '      end if',
    '      if (abs(actual - expected) > 2.0e-12_dp * max(1.0_dp, abs(expected))) then',
    '         print *, "Mismatch: ", label, actual, expected',
    '         error stop 1',
    '      end if',
    '   end subroutine check',
    '   subroutine check_vector(actual, expected, label)',
    '      real(dp), intent(in) :: actual(:) !! Computed vector from the Fortran translation.',
    '      real(dp), intent(in) :: expected(:) !! Same-length golden vector evaluated by upstream R.',
    '      character(len=*), intent(in) :: label !! Name of the computational operation under comparison.',
    '      integer :: i',
    '      if (size(actual) /= size(expected)) error stop "Reference vector size mismatch"',
    '      do i = 1, size(actual)',
    '         call check(actual(i), expected(i), label)',
    '      end do',
    '   end subroutine check_vector',
    'end program test_r_reference')
writeLines(lines, 'test/test_r_reference.f90')
cat('Generated',length(lines),'lines of deterministic R reference checks.\n')
